            )}

            {trip.status === "OPTIONS_READY" && (
              <button
                onClick={() => withAction(() => approveOptions(tripId, trip.options.map(o => o.id)))}
                disabled={loading}
                style={{
                  ...actionBtnStyle,
                  background: "#ffffff",
                  color: "#0a0a0a",
                  opacity: loading ? 0.5 : 1,
                }}
              >
                {loading ? "Approving..." : "Approve All Options"}
              </button>
            )}

            {trip.status === "BOOKING" && (
              <button
                onClick={() => withAction(() => executeBookings(tripId))}
                disabled={loading}
                style={{
                  ...actionBtnStyle,
                  background: "#ffffff",
                  color: "#0a0a0a",
                  opacity: loading ? 0.5 : 1,
                }}
              >
                {loading ? "Booking..." : "Execute Bookings"}
              </button>
            )}

            {trip.status === "CONFIRMED" && (
              <div style={{ display: "flex", gap: 10 }}>
                <input
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Email for confirmations"
                  style={{
                    flex: 1,
                    padding: "14px 16px",
                    background: "#141414",
                    border: "1px solid rgba(255,255,255,0.08)",
                    borderRadius: 10,
                    color: "#f5f5f5",
                    fontFamily: "var(--font-sans)",
                    fontSize: "0.9rem",
                    outline: "none",
                  }}
                />
                <button
                  onClick={() => withAction(() => deliverConfirmations(tripId, email))}
                  disabled={loading}
                  style={{
                    ...actionBtnStyle,
                    width: "auto",
                    padding: "14px 20px",
                    fontSize: "0.85rem",
                    background: "#ffffff",
                    color: "#0a0a0a",
                    opacity: loading ? 0.5 : 1,
                  }}
                >
                  {loading ? "Sending..." : "Deliver"}
                </button>
              </div>
            )}

            {trip.status === "DELIVERED" && (
              <div style={{ textAlign: "center", padding: "28px 16px" }}>
                <p style={{
                  fontFamily: "var(--font-serif)",
                  fontStyle: "italic",
                  fontSize: "1.3rem",
                  color: "#ffffff",
                  marginBottom: 6,
                }}>
                  Trip Booked & Delivered!
                </p>
                <p style={{
                  fontFamily: "var(--font-mono)",
                  fontSize: "0.78rem",
                  color: "var(--text-muted)",
                }}>
                  Confirmations sent to {email}
                </p>
              </div>
            )}

            {!["FUNDED", "OPTIONS_READY", "BOOKING", "CONFIRMED", "DELIVERED"].includes(trip.status) && (
              <p style={{
                fontSize: "0.85rem",
                color: "var(--text-muted)",
                textAlign: "center",
                padding: 20,
                fontStyle: "italic",
              }}>
                Waiting for status change...
              </p>
            )}
          </div>


          {/* Legacy Bookings list */}
          {trip.bookings.length > 0 && (
            <div style={cardStyle}>
              <h3 style={{
                fontFamily: "var(--font-serif)",
                fontSize: "1.15rem",
                fontWeight: 600,
                color: "var(--text-primary)",
                marginBottom: 18,
              }}>
                Confirmed Bookings
              </h3>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {trip.bookings.map((item: any) => (
                  <div key={item.id} style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 14,
                    padding: "14px 16px",
                    background: "#111",
                    border: "1px solid rgba(255,255,255,0.15)",
                    borderRadius: 12,
                  }}>
                    <span style={{ fontSize: "1.3rem" }}>
                      {item.type === "flight" ? "✈️" : item.type === "hotel" ? "🏨" : "🎯"}
                    </span>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <p style={{ fontWeight: 600, fontSize: "0.9rem" }}>{item.name}</p>
                      <p style={{ fontSize: "0.72rem", color: "var(--text-muted)", fontFamily: "var(--font-mono)" }}>
                        {item.confirmationCode}
                      </p>
                    </div>
                    <p style={{ fontFamily: "var(--font-mono)", fontWeight: 700, color: "#ffffff", fontSize: "1rem" }}>
                      ${item.price}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

