export async function createTrip(data: {
  origin: string;
  destination: string;
  startDate: string;
  endDate: string;
  travelers: number;
  preferences: string;
  totalBudget: number;
  spendingLimits?: Partial<Trip['spendingLimits']>;
}): Promise<Trip> {
  const res = await fetch(`${API_BASE}/api/trips`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  });
  return res.json();
}

